const {app,BrowserWindow}=require('electron');const assert=require('node:assert/strict');app.setPath('userData',process.argv[2]);
app.whenReady().then(async()=>{const win=new BrowserWindow({show:false,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false}});await win.loadFile(process.argv[3]);const run=s=>win.webContents.executeJavaScript(s),until=async s=>{for(let i=0;i<150;i++){if(await run(s))return;await new Promise(r=>setTimeout(r,20));}throw Error('UI timeout '+s);},click=label=>run(`[...document.querySelectorAll('button')].find(b=>b.textContent===${JSON.stringify(label)}).click()`);
await until("document.body.textContent.includes('Chosen workspace')");assert.equal(await run("[...document.querySelectorAll('button')].find(b=>b.textContent==='Grant access').disabled"),true);assert.equal(await run("window.calls.some(v=>v.action==='create'||v.action==='decide')"),false);
await run(`for(const [label,value] of [['Agent mail account','a'],['Agent workspace','w']]){const e=document.querySelector('[aria-label="'+label+'"]');Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(e,value);e.dispatchEvent(new Event('change',{bubbles:true}));}`);
await until("document.querySelector('[aria-label=\"Agent workspace\"]').value==='w'");assert.equal(await run("[...document.querySelectorAll('button')].find(b=>b.textContent==='Grant access').disabled"),true);await run("[...document.querySelectorAll('label')].find(e=>e.textContent.includes('I authorize this workspace')).querySelector('input').click()");await until("[...document.querySelectorAll('button')].find(b=>b.textContent==='Grant access').disabled===false");await click('Grant access');await until("window.calls.some(v=>v.action==='create')");
await click('Review request');await until("document.body.textContent.includes('Exact reviewed body')");assert.equal(await run("document.body.textContent.includes('hidden@example.com')"),true);assert.equal(await run("[...document.querySelectorAll('button')].find(b=>b.textContent==='Approve send').disabled"),true);assert.equal(await run("window.calls.some(v=>v.action==='decide')"),false);
await run("[...document.querySelectorAll('label')].find(e=>e.textContent.includes('I reviewed the exact contents')).querySelector('input').click()");await until("[...document.querySelectorAll('button')].find(b=>b.textContent==='Approve send').disabled===false");await click('Approve send');await until("window.calls.some(v=>v.action==='decide'&&v.approve===true)");assert.equal(await run("window.calls.filter(v=>v.action==='decide').length"),1);await run("document.querySelector('[aria-label=\"Reject request from stale-task\"]').click()");await until("window.calls.some(v=>v.action==='decide'&&v.id==='55555555-5555-4555-8555-555555555555'&&v.approve===false)");assert.equal(await run("window.calls.some(v=>v.action==='review'&&v.id==='55555555-5555-4555-8555-555555555555')"),false);console.log('AGENT_UI_PASS');win.destroy();app.quit();}).catch(error=>{console.error(error);app.exit(1);});
